const icon = (name, size = 20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.file}</svg>`;
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const bytes = (value, digits = 1) => { if (value == null) return '—'; if (value === 0) return '0 B'; const n = Math.min(Math.floor(Math.log(Math.max(value, 1)) / Math.log(1000)), 4); return `${(value / 1000 ** n).toFixed(n ? digits : 0)} ${['B', 'KB', 'MB', 'GB', 'TB'][n]}`; };
const count = value => new Intl.NumberFormat(getLocale()).format(value || 0);
const time = value => value ? new Date(value).toLocaleTimeString(getLocale(), { hour: '2-digit', minute: '2-digit' }) : tr('尚未扫描');
const kinds = {cache:tr('缓存'),log:tr('日志'),session:tr('会话'),memory:tr('记忆'),installer:tr('安装包'),other:tr('代码与其他')};
const pages = {overview:tr('总览'),clean:tr('空间清理'),projects:tr('项目清理'),'ai-tools':tr('工具与目录'),settings:tr('设置'),'ai-diagnostics':tr('读取诊断'),assistant:tr('AI 判读'),analyze:tr('磁盘分析')};
function routeForHash(route){return route==='ai'?'projects':route==='ai-storage'?'ai-tools':route==='ai-models'?'settings':pages[route]?route:'overview';}
const initialRoute=location.hash.slice(1)||'overview';
const s = {route:routeForHash(initialRoute),projectFilter:initialRoute==='ai'?'ai':'all',boot:null,overview:null,projects:[],tools:[],scope:'home',selected:new Set(),selectedTools:new Set(),categories:new Set(['cache','log']),personal:false,aiOpen:/^(ai|assistant)/.test(routeForHash(initialRoute)),browser:null,history:[],plan:null,planRows:null,picked:new Set(),all:false,query:'',page:0,error:'',poll:null,lastJob:null,summary:null,analysis:null};
if(s.route!==initialRoute)window.history.replaceState(null,'','#'+s.route);
const app = document.querySelector('#app'), dialog = document.querySelector('#dialog');
// 增量更新：只改动有变化的节点，轮询刷新时保留焦点、滚动位置、展开状态与进行中的动效。
const template = document.createElement('template');
function patch(root, html){template.innerHTML=html;sync(root,template.content);}
function sync(from,to){const old=[...from.childNodes],next=[...to.childNodes];next.forEach((n,i)=>{const o=old[i];if(!o)return from.appendChild(n);if(o.nodeType!==n.nodeType||o.nodeName!==n.nodeName||o.nodeType===1&&o.id!==n.id)return from.replaceChild(n,o);if(o.nodeType!==1){if(o.nodeValue!==n.nodeValue)o.nodeValue=n.nodeValue;return;}update(o,n);});for(let i=old.length-1;i>=next.length;i--)old[i].remove();}
function update(o,n){if(o.hasAttribute('data-typing'))return;const entering=o.classList.contains('mm-enter');for(const {name} of [...o.attributes])if(!n.hasAttribute(name)&&!(name==='open'&&o.tagName==='DETAILS'))o.removeAttribute(name);for(const {name,value} of [...n.attributes])if(o.getAttribute(name)!==value&&!(name==='open'&&o.tagName==='DETAILS'))o.setAttribute(name,value);if(entering)o.classList.add('mm-enter');if(o.tagName==='INPUT'){if(o.type==='checkbox'||o.type==='radio')o.checked=n.hasAttribute('checked');else if(o!==document.activeElement)o.value=n.getAttribute('value')??'';return;}if(o.tagName==='TEXTAREA'){if(o!==document.activeElement)o.value=n.textContent;return;}const chosen=o.tagName==='SELECT'?[...n.querySelectorAll('option')].find(x=>x.hasAttribute('selected'))?.value:null;sync(o,n);if(o.tagName==='SELECT'&&o!==document.activeElement)o.value=chosen??o.options[0]?.value??'';}
const busy = () => s.boot?.jobs.find(j=>j.status==='running');
const scanId = () => s.boot?.scan?.id;
const pathLabel = p => s.boot?.home && p?.startsWith(s.boot.home) ? '~'+p.slice(s.boot.home.length) : p;
const btn = (action,label,opts={}) => `<button type="button" class="btn ${opts.kind||'primary'}" data-action="${action}" ${opts.disabled?'disabled':''} ${opts.extra||''}>${opts.icon?icon(opts.icon,16):''}${label}</button>`;
// 统计行：每项「标签 数值」成组，组间以虚线分隔，替代用「·」拼接的长句；数值为 0 的项弱化显示。
const meta = items => `<span class="mm-meta">${items.filter(Boolean).map(([label,value,raw])=>`<span class="${raw===0?'is-zero':''}"><em>${label}</em><b>${value}</b></span>`).join('')}</span>`;
const countTag = n => `<span class="mm-count">${count(n)}</span>`;
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('show');clearTimeout(s.toast);s.toast=setTimeout(()=>node.classList.remove('show'),6000);}
async function api(action,body){const response=await fetch('/api/'+action,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'content-type':'application/json','x-minorminor-token':s.boot?.token||''},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||tr('操作失败'));return data;}
function modal(html){dialog.innerHTML=html; if(!dialog.open)dialog.showModal();}
function close(){dialog.close();}
const nav = (route,glyph) => `<a href="#${route}" class="nav-item ${s.route===route?'active':''}" ${s.route===route?'aria-current="page"':''}>${icon(glyph,19)}<span>${pages[route]}</span></a>`;
const scanControls = () => ui`<div class="scan-controls"><select id="native-scope" class="scope-select" aria-label="扫描范围" ${busy()?'disabled':''}><option value="home" ${s.scope==='home'?'selected':''}>整个用户目录</option><option value="disk" ${s.scope==='disk'?'selected':''}>启动磁盘数据卷</option></select>${btn('scan',busy()?.kind==='scan'?tr('正在扫描…'):s.boot?.scan?tr('重新扫描'):tr('开始扫描'),{icon:'refresh',disabled:!!busy()})}</div>`;
function heading(title,action=''){return `<section class="page-heading"><h1 id="page-title-${s.route}">${title}</h1>${action}</section>`;}
function progress(){
  const running=busy();
  const job=progressJob(s.boot);
  if(!job)return '';
  const p=scanProgress(job,Date.now(),s.boot.disk),stats=p.stats,isScan=job.kind==='scan';
  if(isScan&&p.fraction!=null){if(s.progressFloor?.id===job.id)p.fraction=Math.max(p.fraction,s.progressFloor.fraction);s.progressFloor={id:job.id,fraction:p.fraction};}
  const labels={preparing:tr('整理扫描索引'),disk:tr('扫描文件'),projects:tr('识别与项目归类'),storage:tr('统计文件夹'),summaries:tr('汇总项目与工具'),models:tr('检测本地模型'),'harness-analysis':tr('识别候选工具'),'read-recovery':tr('核实并补读'),'index-recovery':tr('优化扫描索引'),'index-compress':tr('压缩扫描索引'),'index-verify':tr('核对扫描索引'),complete:tr('同步完成')};
  const title=job.status==='failed'?tr('扫描失败'):job.status==='cancelled'?tr('扫描已停止'):job.status==='complete'?(job.kind==='index-recover'?tr('索引已整理'):tr('扫描完成')):isScan?labels[p.stage]||tr('后台同步扫描'):({cleanup:tr('处理所选文件'),summary:tr('AI 总结'),analysis:tr('AI 判读'),summaries:tr('汇总项目与工具'),models:tr('检测本地模型'),'mole-preview':tr('Mole 预览'),'mole-plan':tr('生成清理清单'),'mole-selection':tr('按清单清理'),'mole-execute':tr('Mole 永久清理'),'harness-analysis':tr('识别候选工具'),advice:tr('AI 风险建议'),'read-recovery':tr('核实并补读'),'directory-size':tr('重新计量'),'model-delete':tr('移除本地模型'),'index-recover':tr('优化扫描索引')})[job.kind]||tr('正在处理');
  const seconds=Math.floor(p.elapsedMs/1000), elapsed=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');
  // 已结束的扫描只保留一行状态，不再占用每页顶部的整块面板；失败仍用完整面板以便重试。
  if(!running&&job.status!=='failed'){const done=job.status==='complete';return `<section class="scan-report native-scan-report ${done?'is-complete':'is-stopped'}" role="status"><span>${icon(done?'check':'help',15)}<strong>${escape(title)}</strong>${isScan&&p.fraction!=null?`<em>${p.estimated?tr('预计进度'):tr('进度')} ${(p.fraction*100).toFixed(1)}%</em>`:''}${stats.files!=null?`<em>${tr('文件')} ${count(stats.files)}</em>`:''}${stats.bytes!=null?`<em>${tr('占用')} ${bytes(stats.bytes)}</em>`:''}${stats.skipped?`<em>${tr('未读取')} ${count(stats.skipped)}</em>`:''}</span><small>${elapsed}</small></section>`;}
  return `<section class="panel native-progress ${job.status==='failed'?'native-progress-failed':''}" role="status" aria-live="polite"><div class="section-header"><h2>${escape(title)}</h2><div class="native-progress-controls">${isScan&&p.fraction!=null?`<strong class="native-progress-percent" title="${escape(tr(stats.estimateSource==='previous-scan'?'按上次同范围扫描估算':'按磁盘已用空间估算'))}">${p.estimated?tr('预计进度'):tr('进度')} ${(p.fraction*100).toFixed(1)}%</strong>`:''}<small>${isScan&&p.step?`${p.step} / ${p.steps} · `:''}${elapsed}</small>${running?btn('cancel',job.cancelling?tr('正在停止…'):tr('停止'),{kind:'secondary',disabled:job.cancelling}):job.status==='failed'?btn('scan',tr('重新扫描'),{kind:'secondary'}):''}</div></div>${running?`<div class="native-activity ${p.fraction!=null?'determinate':''}" role="progressbar" aria-label="${tr(p.estimated?'预计进度':'进度')}" aria-valuemin="0" aria-valuemax="100" ${p.fraction!=null?`aria-valuenow="${(p.fraction*100).toFixed(1)}"`:''}>${p.fraction!=null?`<i style="width:${p.fraction*100}%"></i>`:''}</div>`:''}<div class="native-progress-metrics">${isScan&&stats.diskSnapshot?.free!=null?`<span>${tr('可用空间')} <strong>${bytes(stats.diskSnapshot.free)}</strong></span>`:''}${isScan&&stats.estimatedBytes>0?`<span>${tr('预计扫描总量')} <strong>${bytes(stats.estimatedBytes)}</strong></span>`:''}${stats.files!=null?`<span>${tr('文件')} <strong>${count(stats.files)}</strong></span>`:''}${stats.directories!=null?`<span>${tr('文件夹')} <strong>${count(stats.directories)}</strong></span>`:''}${stats.bytes!=null?`<span>${tr('占用')} <strong>${bytes(stats.bytes)}</strong></span>`:''}${stats.removed!=null?`<span>${tr('已整理索引')} <strong>${count(stats.removed)}</strong></span>`:''}${stats.assignedEntries!=null?`<span>${tr('已归类条目')} <strong>${count(stats.assignedEntries)}</strong></span>`:''}${stats.remainingIndexBytes!=null?`<span>${tr('待回收索引')} <strong>${bytes(stats.remainingIndexBytes)}</strong></span>`:''}${stats.total>0&&stats.remainingIndexBytes==null?`<span>${tr('当前步骤')} <strong>${stats.progressUnit==='bytes'?bytes(stats.completed):count(stats.completed)} / ${stats.progressUnit==='bytes'?bytes(stats.total):count(stats.total)}</strong></span>`:''}${stats.skipped?`<span>${tr('未读取')} <strong>${count(stats.skipped)}</strong></span>`:''}</div>${p.error?`<p class="native-progress-error" role="alert">${escape(tr(p.error))}</p>${p.spaceLimited?`<div class="native-recovery-actions">${btn('storage-recover',tr('优化索引'),{kind:'secondary',disabled:!!busy()})}${btn('storage',tr('索引存储'),{kind:'secondary',disabled:!!busy()})}</div>`:''}`:''}${p.waiting?`<small class="native-progress-wait">${tr('等待当前操作响应，可停止扫描')}</small>`:''}${stats.currentPath?`<code class="native-path" title="${escape(stats.currentPath)}">${escape(pathLabel(stats.currentPath))}</code>`:''}</section>`;
}
function actionBar(){if(!['clean','projects','ai-tools'].includes(s.route))return '';const countSelected=s.selected.size+s.selectedTools.size;const molePlan=s.route==='clean'&&(s.moleLatest||s.boot.molePreview)?.success;if(!s.plan&&!molePlan&&(s.route==='clean'||!countSelected))return '';return `<section class="cleanup-actions"><div class="cleanup-action-summary"><strong>${s.plan?tr('预览 ')+count(s.plan.files)+tr(' 个文件'):tr('已选 ')+count(countSelected)+tr(' 项')}</strong><small>${s.plan?bytes(s.plan.bytes)+tr(' · 移到废纸篓'):tr('缓存、日志')+(s.personal?tr('、会话、记忆'):'')}</small></div><div class="cleanup-action-buttons">${s.plan?btn('show-plan',tr('查看预览'),{kind:'secondary'}):''}${s.route==='clean'&&(s.moleLatest||s.boot.molePreview)?.success?btn('parity-mole-plan',tr('Mole 清单'),{kind:'secondary',disabled:!!busy()||(s.moleLatest||s.boot.molePreview)?.used}):''}${s.route==='clean'&&(s.moleLatest||s.boot.molePreview)?.success?btn('parity-mole-whole',tr('整次 Mole 清理'),{kind:'secondary',disabled:!!busy()||(s.moleLatest||s.boot.molePreview)?.used}):''}${btn(s.route==='clean'?'preview-caches':'preview',tr('预览清理'),{disabled:!!busy()||!scanId()||s.boot.stale||s.route!=='clean'&&!countSelected})}</div></section>`;}
function render(){if(!s.boot)return;const bar=actionBar();patch(app,ui`<aside class="sidebar"><a class="brand" href="#overview"><img src="/icon.svg" width="34" height="34" alt=""/><span>minorminor<span class="brand-dot">.</span></span></a><nav aria-label="主导航">${nav('overview','grid')}${nav('clean','sparkle')}${nav('projects','layers')}<div class="ai-nav-group ${s.aiOpen?'is-open':''}"><button class="nav-item nav-group-toggle" data-action="ai-toggle" aria-expanded="${s.aiOpen}">${icon('layers',19)}<span>AI 专项</span><span class="nav-fold">${s.aiOpen?'▾':'▸'}</span></button><div class="ai-subnav" ${s.aiOpen?'':'hidden'}>${nav('ai-tools','grid')}${nav('ai-diagnostics','help')}${nav('assistant','leaf')}</div></div>${nav('analyze','disk')}</nav><div class="sidebar-bottom">${languagePicker()}${btn('settings',tr('设置'),{kind:'text',icon:'settings'})}<div class="sidebar-version">v${escape(s.boot.version)} · Rust</div></div></aside><div class="workspace ${bar?'has-cleanup-actions':''}"><main id="main">${s.error?`<div class="error-banner" role="alert">${escape(s.error)} ${btn('retry',tr('重新连接'),{kind:'secondary'})}</div>`:''}${page()}</main>${bar}</div>`);requestAnimationFrame(()=>document.documentElement.style.setProperty('--cleanup-actions-height',(document.querySelector('.cleanup-actions')?.getBoundingClientRect().height||0)+'px'));}
function page(){const pre=heading(pages[s.route]||tr('总览'),['overview','settings'].includes(s.route)?'':scanControls())+(s.route==='settings'&&!busy()?'':progress());if(s.route==='overview')return pre+overview();if(s.route==='analyze')return pre+diskRows();if(s.route==='projects')return pre+projects();if(s.route==='clean')return pre+cleanPage();if(s.route==='ai-tools')return pre+tools();if(s.route==='settings')return pre+settingsPage();if(s.route==='ai-diagnostics')return pre+diagnostics();if(s.route==='assistant')return pre+assistant();return pre;}
function overview(){const disk=s.boot.disk,stats=s.boot.scan?.stats;const percent=disk.total?Math.round(disk.used/disk.total*100):0;return ui`<section class="overview-hero"><section class="panel scan-controls-panel"><h2>扫描文件</h2><code class="scan-scope-path">${escape(s.scope==='home'?s.boot.home:'/')}</code>${scanControls()}${s.boot.scan?ui`<small>${time(s.boot.scan.createdAt)} 更新${s.boot.stale?tr(' · 清理后需重新扫描'):''}</small>`:''}</section><section class="storage-card"><h3>${icon('disk',17)}磁盘空间</h3><div class="disk-ring" style="--used:${percent}%"><div class="ring-inner"><span>可用空间</span><strong>${bytes(disk.free).split(' ')[0]}<small>${bytes(disk.free).split(' ')[1]}</small></strong><span>共 ${bytes(disk.total)}</span></div></div><div class="disk-legend"><span>已使用 <strong>${bytes(disk.used)}</strong></span><span>可用 <strong>${bytes(disk.free)}</strong></span></div></section></section><div class="stats-strip"><div><div><span>已扫描占用</span><strong>${stats?bytes(stats.bytes):tr('待扫描')}</strong></div></div><div><div><span>已发现项目</span><strong>${count(s.projects.length)}</strong></div></div><div><div><span>读取错误</span><strong>${stats?count(stats.skipped):'—'}</strong></div>${stats?.skipped?btn('errors',tr('查看明细'),{kind:'text'}):''}</div></div><section class="panel"><div class="section-header"><h2>项目占用</h2><a href="#projects" class="text-button">查看全部 ${icon('arrow',15)}</a></div>${s.projects.slice(0,5).map(p=>`<article class="native-summary-row"><strong>${escape(p.name)}</strong><code>${escape(pathLabel(p.path))}</code><b>${bytes(p.bytes)}</b></article>`).join('')||tr('<p>尚未扫描</p>')}</section>${s.boot.lastReceipt?ui`<section class="panel"><div class="section-header"><h2>最近整理</h2>${btn('receipts',tr('查看逐文件去向'),{kind:'secondary'})}</div></section>`:''}`;}
function diskRows(){const live=busy()?.kind==='scan'?busy().stats?.rows:null;const source=live&&Object.keys(live).length?{scan:{root:s.boot.home},rows:Object.values(live).sort((a,b)=>b.bytes-a.bytes)}:s.overview;if(!source)return tr('<section class="panel empty-state">尚未扫描</section>');const total=live?busy().stats.bytes||1:s.boot.scan?.stats.bytes||1;return `<section class="panel"><div class="section-header"><h2>${escape(source.scan.root)}</h2><strong>${bytes(total)}</strong></div>${source.rows.map(row=>ui`<article class="native-disk-row"><button class="text-button" data-action="disk-open" data-path="${escape(row.path)}">${icon(row.directory?'box':'file',18)}${escape(row.name||'/')}</button><div class="native-bar"><i style="width:${Math.min(100,row.bytes/total*100)}%"></i></div><strong>${row.skipped?"≥ ":""}${bytes(row.bytes)}</strong><small>${count(row.files)} 个文件</small></article>`).join('')}</section>${fileBrowser()}`;}
function options(){return ui`<div class="project-clean-options"><div class="project-category-options">${['cache','log','session','memory'].map(kind=>`<label><input type="checkbox" data-category="${kind}" ${s.categories.has(kind)?'checked':''} ${['session','memory'].includes(kind)&&!s.personal?'disabled':''}/> ${kinds[kind]}</label>`).join('')}</div><label><input type="checkbox" id="native-personal" ${s.personal?'checked':''}/> 启用会话和记忆审阅</label></div>`;}
function projects(){const rows=s.projects.filter(p=>(s.projectFilter!=='ai'||p.sessions||p.categories.session?.files||p.categories.memory?.files)&&(!s.query||(p.name+' '+p.path).toLowerCase().includes(s.query.toLowerCase())));return ui`<section class="panel project-panel"><div class="section-header"><h2>项目清单${countTag(rows.length)}</h2>${exportFormat()}${btn('export-projects',tr('导出到下载'),{kind:'text'})}</div><div class="parity-filters"><select id="native-project-filter" aria-label="${tr('项目范围')}"><option value="all" ${s.projectFilter==='all'?'selected':''}>全部项目</option><option value="ai" ${s.projectFilter==='ai'?'selected':''}>含 AI 记录</option></select></div>${options()}<input class="clean-search" id="native-search" type="search" placeholder="搜索项目或路径…" aria-label="搜索项目" value="${escape(s.query)}"/>${s.boot.stale?tr('<p class="clean-plan-warning">整理后需要重新扫描以更新占用</p>'):''}<div class="project-grid">${rows.slice(s.page*12,s.page*12+12).map(p=>ui`<article><div class="project-line"><label class="project-pick-label"><input type="checkbox" data-project="${p.id}" aria-label="勾选 ${escape(p.name)}" ${s.selected.has(p.id)?'checked':''} ${busy()||s.boot.stale?'disabled':''}/></label><button class="project-open" data-action="project-open" data-id="${p.id}"><b>${escape(p.name)}</b>${meta([[tr('文件'),count(p.files),p.files||0],[tr('关联记录'),count(p.sessions),p.sessions||0]])}</button><b>${bytes(p.bytes)}</b></div><code class="project-path">${escape(pathLabel(p.path))}</code>${p.description?`<p class="project-size-other">${escape(p.description)}</p>`:''}<div class="project-size-categories">${['cache','log','session','memory'].map(k=>ui`<button class="project-size-category ${k} ${p.categories[k]?.bytes?'':'is-empty'}" data-action="project-kind" data-id="${p.id}" data-kind="${k}"><span>${kinds[k]}</span><strong>${bytes(p.categories[k]?.bytes||0)}</strong><small>${count(p.categories[k]?.files||0)} 个文件</small></button>`).join('')}</div><p class="project-size-other">代码与其他 ${bytes(p.categories.other?.bytes||0)}</p><div class="inventory-row-footer">${btn('project-open',tr('展开文件'),{kind:'secondary',extra:`data-id="${p.id}"`})}${btn('parity-project-details',tr('关联与用途'),{kind:'text',extra:`data-id="${p.id}"`})}${btn('project-summary',tr('AI 总结'),{kind:'text',disabled:!!busy(),extra:`data-id="${p.id}"`})}</div></article>`).join('')||tr('<p class="empty-state">没有匹配的项目；先扫描用户目录</p>')}</div>${pagination(s.page*12,12,rows.length,'project-page')}${fileBrowser()}</section>`;}
function originalTools(){return ui`<section class="panel agent-inventory"><div class="section-header"><h2>工具与目录${countTag(s.tools.length)}</h2>${exportFormat()}${btn('export-tools',tr('导出到下载'),{kind:'text'})}</div><div class="agent-inventory-rows">${s.tools.map(t=>ui`<article><div class="inventory-row-heading"><label><input type="checkbox" data-tool="${t.id}" ${s.selectedTools.has(t.id)?'checked':''} ${busy()||s.boot.stale?'disabled':''}/> <strong>${escape(t.name)}</strong></label><span class="quiet-tag">${t.uncertain?tr('身份待确认'):t.evidence.installation?tr('发现安装'):tr('发现本地数据')}</span><b>${bytes(t.bytes)}</b></div><code>${escape(pathLabel(t.path))}</code><div class="inventory-row-footer">${meta([[tr('文件'),count(t.files),t.files||0]])}${Object.entries(t.categories||{}).map(([kind,c])=>btn('parity-tool-category',escape(kinds[kind]||kind)+' '+bytes(c.bytes),{kind:'text',extra:`data-id="${t.id}" data-kind="${kind}"`})).join('')}${btn('tool-open',tr('展开文件'),{kind:'secondary',extra:`data-id="${t.id}"`})}${btn('tool-evidence',tr('识别依据'),{kind:'text',extra:`data-id="${t.id}"`})}</div></article>`).join('')||tr('<p>扫描后查看识别结果</p>')}</div>${fileBrowser()}</section>`;}
function originalCleanPage(){return ui`<section class="panel"><div class="section-header"><div><h2>缓存与日志</h2><p>${s.boot.scan?time(s.boot.scan.createdAt)+tr(' 更新'):tr('尚未扫描')}</p></div>${btn('preview-caches',tr('生成逐文件预览'),{disabled:!scanId()||!!busy()||s.boot.stale})}</div>${s.plan?ui`${meta([[tr('预览文件'),count(s.plan.files),s.plan.files||0],[tr('可释放'),bytes(s.plan.bytes)]])}${btn('show-plan',tr('查看并勾选清理范围'),{kind:'secondary'})}`:''}${s.boot.lastReceipt?btn('receipts',tr('查看整理记录'),{kind:'text'}):''}</section><section class="panel"><details><summary>Mole 引擎 · 只读预览</summary><div class="native-mole-actions">${['clean','purge','installer','optimize'].map(command=>btn('mole',command+' --dry-run',{kind:'secondary',disabled:!!busy()||!s.boot.mole.available,extra:`data-command="${command}"`})).join('')}</div></details></section>`;}
function fileBrowser(){const b=s.browser;if(!b)return '';return ui`<section class="project-file-explorer"><div class="section-header"><h3>文件与文件夹</h3><div>${s.history.length?btn('file-back',tr('上一级'),{kind:'secondary'}):''}${b.rootId?btn('parity-measure',tr('重新计量'),{kind:'secondary',disabled:!!busy(),extra:`data-id="${b.rootId}"`}):''}${b.rootId?btn('summary',tr('总结当前文件夹'),{kind:'text',disabled:!!busy(),extra:`data-id="${b.rootId}"`}):''}${btn('files-close',tr('收起'),{kind:'text'})}</div></div><code class="native-path">${escape(pathLabel(b.path))}</code><div class="parity-filters"><input id="parity-file-query" placeholder="${tr('搜索文件')}" value="${escape(b.scope.query||'')}"/><select id="parity-file-sort"><option value="size">${tr('按大小')}</option><option value="name" ${b.scope.sort==='name'?'selected':''}>${tr('按名称')}</option><option value="time" ${b.scope.sort==='time'?'selected':''}>${tr('按修改时间')}</option></select>${btn('parity-file-filter',tr('筛选'),{kind:'secondary'})}</div><div class="file-explorer-rows">${b.rows.map(row=>row.directory?ui`<article class="native-file-row"><button class="text-button" data-action="${row.projectId?'project-open':'directory'}" data-id="${row.projectId||row.id}">${icon('box',18)}${escape(row.name)}</button><div><strong>${row.skipped?"≥ ":""}${bytes(row.bytes)}</strong>${meta([[tr('文件'),count(row.files),row.files||0],[tr('子文件夹'),count(row.directories),row.directories||0],row.skipped&&[tr('未读完整'),count(row.skipped)]])}</div>${row.canSummarize?btn('summary',tr('AI 总结'),{kind:'text',disabled:!!busy(),extra:`data-id="${row.id}"`}):''}</article>`:ui`<details class="file-entry"><summary class="native-file-row"><span>${icon('file',16)} ${escape(row.name)}</span><span><strong>${bytes(row.bytes)}</strong><small>${kinds[row.kind]||row.kind}</small></span></summary><div class="file-entry-details"><code>${escape(row.path)}</code><p>${escape(tr(row.purpose))}</p>${meta([[tr('磁盘占用'),bytes(row.bytes)],[tr('内容大小'),bytes(row.logicalBytes)]])}<div class="inventory-row-footer">${row.canRead?btn('inspect',tr('查看内容片段'),{kind:'secondary',extra:`data-id="${row.id}"`}):''}${row.canSummarize?btn('summary',tr('AI 总结'),{kind:'text',disabled:!!busy(),extra:`data-id="${row.id}"`}):''}</div>${s.summary?.path===row.path?`<p class="ai-file-summary">${escape(s.summary.summary)}</p>`:''}</div></details>`).join('')||tr('<p>此目录或类别下没有文件</p>')}</div>${pagination(b.offset,100,b.total,'files-page')}</section>`;}
function pagination(offset,size,total,action){return `<div class="clean-pagination"><span>${total?offset+1:0}–${Math.min(offset+size,total)} / ${count(total)}</span><div>${btn(action,tr('上一页'),{kind:'secondary',disabled:!offset,extra:`data-offset="${Math.max(0,offset-size)}"`})}${btn(action,tr('下一页'),{kind:'secondary',disabled:offset+size>=total,extra:`data-offset="${offset+size}"`})}</div></div>`;}
function settingsRow(action,label,glyph,value='',disabled=false){return `<button class="settings-action" data-action="${action}" ${disabled?'disabled':''}><span class="settings-action-icon">${icon(glyph,18)}</span><span>${tr(label)}</span>${value?`<small>${escape(value)}</small>`:''}${icon('chevron',15)}</button>`;}
function settingsPage(){
  const c=s.boot.config;
  return `<div class="settings-layout"><div class="settings-main"><section class="panel settings-connection"><div class="settings-card-header"><h2>${icon('monitor',17)}${tr('模型连接')}</h2>${btn('config',tr('配置连接'),{kind:'secondary',icon:'settings'})}</div><div class="settings-connection-body"><div class="settings-connection-title"><strong>${escape(c.model||tr('未配置模型'))}</strong><span class="quiet-tag">${c.provider==='ollama'?'Ollama':'Chat Completions'}</span></div><code class="settings-endpoint" title="${escape(c.baseUrl)}">${escape(c.baseUrl)}</code></div></section>${models()}</div><aside class="settings-aside"><section class="panel settings-group"><div class="settings-card-header"><h2>${tr('存储与权限')}</h2></div>${settingsRow('privacy','文件访问权限','shield')}${settingsRow('storage','索引存储','disk',bytes(s.boot.indexStorage?.bytes),!!busy())}</section><section class="panel settings-group"><div class="settings-card-header"><h2>${tr('数据与记录')}</h2></div>${settingsRow('parity-history','整理历史','clock')}${settingsRow('parity-import','导入 Web 历史','download')}${s.boot.legacy?settingsRow('parity-legacy','查看 Web 历史','file'):''}</section></aside><footer class="settings-about"><span>Minorminor ${escape(s.boot.version)} <small>Rust / WebKit</small></span><code title="${escape(s.boot.home)}">${escape(s.boot.home)}</code></footer></div>`;
}
function models(){
  const rows=s.boot.models?.models||[];
  return `<section class="panel settings-models"><div class="settings-card-header"><h2>${icon('box',17)}${tr('本地模型')}${countTag(rows.length)}</h2>${btn('models',tr('检测模型'),{kind:'secondary',icon:'refresh',disabled:!!busy()})}</div>${rows.map(m=>{const details=[m.details?.family,m.details?.parameter_size,m.details?.quantization_level].filter(Boolean).join(' / ');return `<article class="settings-model"><div class="settings-model-top"><strong title="${escape(m.name)}">${escape(m.name)}</strong><span class="settings-model-status ${m.running===true?'is-running':''}">${m.running===true?tr('正在使用'):m.running===false?tr('未加载'):tr('运行状态未知')}</span><b>${bytes(m.bytes)}</b></div>${details?`<p class="settings-model-details">${escape(details)}</p>`:''}<div class="settings-model-bottom"><code title="${escape(m.digest)}">${escape(m.digest?.slice(0,20))}${m.digest?.length>20?'…':''}</code><div class="settings-model-actions">${btn('parity-use-model',tr('使用此模型'),{kind:'secondary',disabled:!!busy(),extra:`data-id="${m.id}"`})}${btn('model-review',tr('审阅移除'),{kind:'text',disabled:!!busy()||m.running===true,extra:`data-id="${m.id}"`})}</div></div></article>`;}).join('')||`<div class="settings-model-empty">${icon('box',28)}<p>${tr('暂无模型记录')}</p></div>`}</section>`;
}
function diagnostics(){return ui`<section class="panel"><div class="section-header"><h2>读取与关联诊断</h2><div>${btn('errors',tr('扫描错误'),{kind:'secondary'})}${btn('errors-retry',tr('核实并补读'),{kind:'secondary',disabled:!!busy()||!scanId()})}${btn('associations',tr('关联文件'),{kind:'secondary'})}${btn('privacy',tr('macOS 文件访问权限'),{kind:'text'})}</div></div>${(st=>meta([[tr('读取失败'),count(st.skipped),st.skipped||0],[tr('符号链接跳过'),count(st.links),st.links||0],[tr('跨卷跳过'),count(st.mounts),st.mounts||0]]))(s.boot.scan?.stats||{})}</section>`;}
function originalAssistant(){const c=s.boot.config;return ui`<section class="panel"><div class="section-header"><h2>AI 判读</h2><span class="quiet-tag">文档读取已禁用</span></div><div class="inventory-row-footer">${btn('config',c.configured?tr('模型连接 · ')+c.model:tr('连接模型'),{kind:'secondary'})}${btn('analyze',tr('审阅元数据并判读'),{disabled:!c.configured||!scanId()||!!busy()})}</div>${s.analysis?`<p>${escape(s.analysis.summary||'')}</p>${s.analysis.items.map(i=>`<article class="native-summary-row"><strong>${escape(s.tools.find(t=>t.id===i.id)?.name||tr('工具'))}</strong><div><p>${escape(i.purpose)}</p><small>${escape(i.uncertainty)}</small></div></article>`).join('')}`:''}</section>`;}
async function loadPage(){if(!scanId())return;const [overview,projects,tools,harnesses]=await Promise.all([api('overview',{scanId:scanId()}),api('projects',{scanId:scanId()}),api('tools',{scanId:scanId()}),api('harnesses',{scanId:scanId()})]);s.overview=overview;s.projects=projects.rows;s.tools=tools.rows;s.harnesses=harnesses;}
function restoreScanScope(){const job=[...(s.boot?.jobs||[])].reverse().find(j=>j.kind==='scan');const id=job?.id||s.boot?.scan?.id;if(id&&s.scopeScanId!==id){s.scope=scanScope(s.boot);s.scopeScanId=id;}}
async function refresh(){s.boot=await api('bootstrap');restoreScanScope();s.advice=s.boot.advice||s.advice;s.moleLatest=s.boot.molePreview||null;if(restoreLocale(s.boot.preferences))return;render();if(busy())schedulePoll();if(busy()?.kind!=='index-recover')await loadPage();render();}
function schedulePoll(){clearTimeout(s.poll);s.poll=setTimeout(poll,650);}
async function poll(){try {let pageLoaded=false;const reloadPage=async()=>{await loadPage();pageLoaded=true;};const before=scanId();s.boot.jobs=(await api('jobs')).jobs;restoreScanScope();const running=busy();if(running){render();schedulePoll();return;}render();const terminal=[...s.boot.jobs].reverse().find(j=>j.finishedAt);if(terminal?.kind==='scan'&&['failed','cancelled'].includes(terminal.status)){s.lastJob=terminal.id;render();return;}s.boot=await api('bootstrap');s.moleLatest=s.boot.molePreview||null;s.error='';render();const finished=[...s.boot.jobs].reverse().find(j=>j.finishedAt);if(finished&&s.lastJob!==finished.id){s.lastJob=finished.id;if(finished.status==='failed')toast(finished.error||tr('任务未完成'));if(finished.kind==='read-recovery'&&finished.status==='complete'){await reloadPage();toast(tr('核实与补读已完成'));await diagnostic('errors');}if(finished.kind==='directory-size'&&finished.status==='complete'){await reloadPage();if(s.browser)await browse(s.browser.scope);}if(finished.kind==='index-recover'&&finished.status==='complete'){s.browser=null;s.history=[];s.selected.clear();s.selectedTools.clear();s.plan=null;s.overview=null;s.projects=[];s.tools=[];await reloadPage();toast(finished.result?.compactionWarning||tr('索引已整理'));}if(finished.kind==='scan'&&finished.status==='complete'){s.browser=null;s.history=[];s.selected.clear();s.selectedTools.clear();s.plan=null;await reloadPage();}if(finished.kind==='cleanup'){s.plan=null;close();toast(tr('整理已结束，请查看逐文件去向'));await receipt(finished.id);}if(finished.kind==='summary'&&finished.status==='complete'){s.summary=finished.result;showSummary(finished.result);}if(finished.kind==='analysis'&&finished.status==='complete')s.analysis=finished.result;if(finished.kind==='mole-preview'&&finished.status==='complete'){s.moleLatest=finished.result;modal(`<h2 id="dialog-title">Mole · ${escape(finished.result.command)}</h2><pre class="native-output">${escape(finished.result.output)}</pre><div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}if(finished.kind==='advice'&&finished.status==='complete')s.advice=finished.result;if(finished.kind==='harness-analysis'&&finished.status==='complete'){s.harnessAnswers=finished.result;await reloadPage();}if(finished.kind==='mole-plan'&&finished.status==='complete'){s.molePlan=finished.result;showMolePlan();}if(['mole-selection','mole-execute'].includes(finished.kind)){await receipt(finished.id);}if(finished.kind==='model-delete'){toast(finished.status==='complete'?tr('模型已移除'):tr('请刷新模型列表核对'));}}if(before!==scanId()&&!pageLoaded)await reloadPage();render();}catch(error){s.error=tr(error.message);render();schedulePoll();}}
async function start(action,body={}){const result=await api(action,body);if(action==='scan'&&result.stats?.diskSnapshot)s.boot.disk={...s.boot.disk,...result.stats.diskSnapshot};s.lastJob=null;s.error='';s.boot.jobs.push({id:result.id,kind:action==='scan'?'scan':action==='execute'?'cleanup':action==='ai/summary'?'summary':action==='ai/analyze'?'analysis':action==='models/delete'?'model-delete':action==='mole/preview'?'mole-preview':action,status:'running',createdAt:new Date().toISOString(),stats:result.stats||{stage:'preparing'}});render();schedulePoll();return result;}
async function browse(scope,remember=false){if(remember&&s.browser)s.history.push(s.browser.scope);s.browser=await api('files',{...scope,scanId:scanId()});render();document.querySelector('.project-file-explorer')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
async function preview(all=false){modal(tr('<h2 id="dialog-title" data-waiting>正在生成预览…</h2>'));s.plan=await api('preview',{scanId:scanId(),projects:[...s.selected],tools:[...s.selectedTools],categories:all?['cache','log','installer']:[...s.categories],personal:s.personal,allCaches:all});s.picked.clear();s.all=false;await showPlan(0);render();}
async function showPlan(offset=0){if(!s.plan)return;s.planRows=await api('preview/files',{planId:s.plan.id,offset});const p=s.plan,r=s.planRows;modal(ui`<h2 id="dialog-title">预览清理</h2>${meta([[tr('可整理文件'),count(p.files),p.files||0],[tr('可释放'),bytes(p.bytes)]])}<label><input type="checkbox" id="native-plan-all" ${s.all?'checked':''}/> 选择此次预览的全部 ${count(p.files)} 个文件</label><div class="native-plan-list">${r.rows.map(row=>`<article class="native-plan-row"><label><input type="checkbox" data-plan-file="${row.id}" ${s.all||s.picked.has(row.id)?'checked':''}/> <code>${escape(row.path)}</code></label><span>${kinds[row.kind]} · ${bytes(row.bytes)}</span></article>`).join('')||tr('<p>没有符合条件的文件</p>')}</div>${pagination(r.offset,100,r.total,'plan-page')}${p.retained.length?ui`<details><summary>保留文件及原因 · 前 ${p.retained.length} 项</summary>${p.retained.map(row=>`<p><code>${escape(row.path)}</code><br/>${escape(tr(row.reason))}</p>`).join('')}</details>`:''}${p.personal?tr('<label><input type="checkbox" id="native-personal-confirm"/> 确认处理会话或记忆可能影响历史记录和长期记忆</label>'):''}<label class="native-method">${tr('处理方式')}<select id="parity-method"><option value="trash">${tr('移到废纸篓')}</option><option value="permanent">${tr('永久删除')}</option></select></label><label data-permanent-ack hidden><input type="checkbox" id="parity-permanent-confirm"/> ${tr('若选择永久删除，我确认所勾选文件无法从废纸篓恢复')}</label><div class="dialog-actions native-plan-actions">${exportFormat()}${btn('export-plan',tr('导出清单'),{kind:'secondary'})}${btn('close',tr('取消'),{kind:'secondary'})}${btn('execute',tr('确认处理勾选文件'),{disabled:!p.files,icon:'trash'})}</div>`);}
function showSummary(result){modal(ui`<h2 id="dialog-title">${escape(result.name)} · AI 总结</h2><p class="ai-summary-output">${escape(result.summary)}</p>${result.points?.length?`<ul>${result.points.map(p=>`<li>${escape(p)}</li>`).join('')}</ul>`:''}<small>${escape(result.limitations||'')} · ${result.coverage.filesRead} 个内容文件${result.coverage.truncated?tr(' · 抽读'):''} · ${escape(result.model)}</small><div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}
async function summary(id){if(!s.boot.config.configured){configDialog();return;}modal(tr('<h2 id="dialog-title" data-waiting>正在准备点选内容…</h2>'));const p=await api('ai/prepare',{id,scanId:scanId()});s.pendingSummary=p;modal(ui`<h2 id="dialog-title">${escape(p.name)} · AI 总结</h2><code>${escape(p.path)}</code><p>读取 ${count(p.coverage.filesRead)} 个文件 · ${bytes(p.coverage.bytesRead)}${p.coverage.truncated?tr(' · 抽读'):''}</p><p>发送至 ${escape(p.destination)} · ${escape(p.model)}</p><div class="summary-file-list">${p.files.map(f=>`<small>${escape(f.name)}${f.truncated?tr(' · 片段'):''}</small>`).join('')}</div><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('summary-confirm',tr('发送所选内容并总结'))}</div>`);}
function accessDialog(scan=false){modal(ui`<h2 id="dialog-title">文件访问权限</h2><p>在系统设置中添加当前应用并开启「完全磁盘访问」，可减少逐目录询问。最终开关需由你确认。</p>${s.boot.access?.appPath?`<code class="native-path">${escape(s.boot.access.appPath)}</code>`:ui`<p>建议从打包的 Minorminor.app 启动，保持应用身份与路径一致。</p>`}<div class="inventory-row-footer">${btn('privacy-open',tr('打开系统授权'),{kind:'secondary'})}</div><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${scan?btn('access-scan',tr('使用当前权限开始扫描')):btn('close',tr('完成'))}</div>`);}
async function storageDialog(){const r=await api('storage/info',{});modal(ui`<h2 id="dialog-title">索引存储</h2><code class="native-path">${escape(r.path)}</code><div class="mm-storage-metrics">${meta([[tr('索引占用'),bytes(r.bytes)],[tr('可复用空间'),bytes(r.reusableBytes)],[tr('磁盘可用'),bytes(r.freeBytes)]])}</div><div class="dialog-actions">${btn('storage-recover',tr('优化索引'),{kind:'secondary',disabled:!!busy()})}${btn('storage-reset',tr('重建索引'),{kind:'secondary',disabled:!!busy()})}${btn('close',tr('关闭'))}</div>`);}
function resetIndexDialog(){modal(ui`<h2 id="dialog-title">重建扫描索引</h2><p>清除可重新生成的扫描结果，保留设置与清理记录。不会删除磁盘上的文件。</p><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('storage-reset-confirm',tr('确认重建索引'))}</div>`);}
function configDialog(){const c=s.boot.config;modal(ui`<h2 id="dialog-title">模型连接</h2><form id="native-config"><label>接口类型<select name="provider"><option value="ollama" ${c.provider==='ollama'?'selected':''}>本机 Ollama</option><option value="compatible" ${c.provider==='compatible'?'selected':''}>Chat Completions 兼容接口</option></select></label><label>基础地址<input name="baseUrl" type="url" value="${escape(c.baseUrl)}" required/></label><label>模型名称<input name="model" value="${escape(c.model)}" required/></label><label>API Key<input name="apiKey" type="password" autocomplete="off" placeholder="${c.hasKey?tr('已在服务内存中保存'):tr('仅保存在当前进程内存中')}"/></label><span class="quiet-tag">AI 分析文档读取权限：禁用</span><label><input type="checkbox" name="harnessAnalysis" ${s.boot.harnessAnalysis?'checked':''}/> ${tr('扫描时自动识别候选工具（仅元数据）')}</label><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}<button class="btn primary" type="submit">保存连接</button></div></form>`);}
async function receipt(jobId=s.boot.lastReceipt?.jobId,offset=0){const r=await api('receipts',{jobId,offset});s.receiptJob=jobId;modal(ui`<h2 id="dialog-title">逐文件去向</h2><div class="native-plan-list">${r.rows.map(row=>`<article><strong>${({moving:tr('移动前记录'),moved:tr('已移到废纸篓'),staged:tr('永久删除前暂存'),deleted:tr('已永久删除'),started:tr('已开始'),finished:tr('已完成'),failed:tr('失败'),skipped:tr('已保留'),'restored-stale':tr('变化后已放回'),'needs-review':tr('需要核对')})[row.status]||escape(row.status)}</strong><code class="native-path">${escape(row.path)}</code>${row.target?`<code class="native-path">→ ${escape(row.target)}</code>`:''}<small>${bytes(row.bytes)} ${escape(tr(row.reason))}</small></article>`).join('')}</div>${pagination(offset,100,r.total,'receipt-page')}<div class="dialog-actions">${exportFormat()}${btn('export-receipts',tr('导出到下载'),{kind:'secondary'})}${btn('close',tr('关闭'))}</div>`);}
function diagnosticLabel(value){return tr(({permission:'权限不足',missing:'路径失效','cloud-timeout':'云端超时',timeout:'读取超时',format:'格式异常',recovered:'已补读',resolved:'已排除误报',unsafe:'路径不安全','read-error':'其他读取异常'})[value]||value);}
async function diagnostic(action,offset=0,filters){s.diagnosticType=action;if(filters)s.diagnosticFilters=filters;const f=s.diagnosticFilters||{};const r=await api(action,{scanId:scanId(),offset,...f});const statuses=action==='errors'?['permission','missing','cloud-timeout','timeout','format','recovered','resolved','unsafe','read-error']:['readable','recovered','missing','unreadable','unsafe','ambiguous'];modal(`<h2 id="dialog-title">${action==='errors'?tr('扫描错误'):tr('关联文件')}</h2><div class="parity-filters"><input id="parity-diagnostic-query" placeholder="${tr('搜索路径或原因')}" value="${escape(f.query||'')}"/><select id="parity-diagnostic-status"><option value="">${tr('全部状态')}</option>${statuses.map(v=>`<option value="${v}" ${f.status===v?'selected':''}>${escape(diagnosticLabel(v))}</option>`).join('')}</select>${btn('parity-diagnostic-filter',tr('筛选'),{kind:'secondary'})}</div>${r.summary?meta(Object.entries(r.summary).map(([key,n])=>[diagnosticLabel(key),count(n),n])):''}<div class="native-plan-list">${r.rows.map(row=>`<article><strong>${escape(diagnosticLabel(['recovered','resolved'].includes(row.status)?row.status:row.category||row.status||row.code))} ${row.code?escape(row.code):''}${row.project?' · '+escape(row.project):''}</strong><code class="native-path">${escape(row.path)}</code><p>${escape(tr(row.reason))}</p>${row.actualPath?`<code class="native-path">${escape(row.actualPath)}</code>`:''}${row.indexedPath&&row.path!==row.indexedPath?`<code>${tr('索引路径：')}${escape(row.indexedPath)}</code>`:''}</article>`).join('')||`<p>${tr('没有记录')}</p>`}</div>${pagination(offset,100,r.total,'diagnostic-page').replaceAll('data-action="diagnostic-page"',`data-action="diagnostic-page" data-type="${action}"`)}<div class="dialog-actions">${exportFormat()}${btn('parity-diagnostic-export',tr('导出全部记录'),{kind:'secondary'})}${action==='errors'?btn('errors-retry',tr('核实并补读'),{kind:'secondary',disabled:!!busy()}):''}${btn('close',tr('关闭'))}</div>`);}
window.addEventListener('focus',()=>{if(s.boot){clearTimeout(s.poll);poll();}});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);s.route=routeForHash(route);if(route==='ai'){s.projectFilter='ai';s.selected.clear();s.selectedTools.clear();s.plan=null;}if(s.route!==route)window.history.replaceState(null,'','#'+s.route);s.aiOpen=s.route.startsWith('ai')||s.route==='assistant';s.query='';s.page=0;s.browser=null;s.history=[];render();window.scrollTo(0,0);});
document.addEventListener('input',event=>{if(event.target.id==='native-search'){s.query=event.target.value;s.page=0;const cursor=event.target.selectionStart;render();const node=document.querySelector('#native-search');node.focus();node.setSelectionRange(cursor,cursor);}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='native-scope')s.scope=t.value;if(t.id==='native-project-filter'){s.projectFilter=t.value;s.page=0;s.selected.clear();s.selectedTools.clear();s.plan=null;s.browser=null;s.history=[];}if(t.dataset.project)t.checked?s.selected.add(t.dataset.project):s.selected.delete(t.dataset.project);if(t.dataset.tool)t.checked?s.selectedTools.add(t.dataset.tool):s.selectedTools.delete(t.dataset.tool);if(t.dataset.category)t.checked?s.categories.add(t.dataset.category):s.categories.delete(t.dataset.category);if(t.id==='native-personal'){s.personal=t.checked;if(!s.personal){s.categories.delete('session');s.categories.delete('memory');}}if(t.id==='native-plan-all'){s.all=t.checked;s.picked.clear();showPlan(s.planRows.offset).catch(e=>toast(tr(e.message)));return;}if(t.dataset.planFile){if(s.all){s.all=false;s.picked=new Set(s.planRows.rows.map(r=>r.id));}t.checked?s.picked.add(t.dataset.planFile):s.picked.delete(t.dataset.planFile);return;}if(!dialog.open)render();});
document.addEventListener('submit',async event=>{if(event.target.id!=='native-config')return;event.preventDefault();try{const data=Object.fromEntries(new FormData(event.target));data.harnessAnalysis=new FormData(event.target).has('harnessAnalysis');await api('ai/config',data);close();await refresh();toast(tr('模型连接已保存'));}catch(e){toast(tr(e.message));}});
document.addEventListener('click',async event=>{const t=event.target.closest('[data-action]');if(!t||t.disabled)return;const a=t.dataset.action;try{if(a==='close')return close();if(a==='retry')return await refresh();if(a==='ai-toggle'){s.aiOpen=!s.aiOpen;return render();}if(a==='scan'){if(s.boot.access&&!s.boot.access.setupShown)return accessDialog(true);s.browser=null;return await start('scan',{scope:s.scope});}if(a==='cancel'){const job=busy();if(job)job.cancelling=true;render();await api('cancel',{});schedulePoll();return;}if(a==='privacy')return accessDialog(false);if(a==='privacy-open'){await api('privacy',{});return;}if(a==='access-scan'){s.boot.access=await api('access/acknowledge',{});close();s.browser=null;return await start('scan',{scope:s.scope});}if(a==='storage')return await storageDialog();if(a==='storage-recover'){close();return await start('storage/recover',{});}if(a==='storage-reset')return resetIndexDialog();if(a==='storage-reset-confirm'){close();s.browser=null;s.projects=[];s.tools=[];s.selected.clear();s.selectedTools.clear();s.plan=null;return await start('storage/recover',{reset:true,confirmation:'REBUILD_SCAN_INDEX'});}if(a==='config')return configDialog();if(a==='settings'){close();location.hash='settings';return;}if(a==='project-page'){s.page=Number(t.dataset.offset)/12;return render();}if(a==='project-open'||a==='project-kind'){s.history=[];return await browse({project:t.dataset.id,kind:t.dataset.kind||'tree',offset:0});}if(a==='tool-open'){s.history=[];return await browse({tool:t.dataset.id,kind:'tree',offset:0});}if(a==='disk-open'){s.history=[];const root=await api('files',{scanId:scanId(),kind:'tree'});const row=root.rows.find(r=>r.path===t.dataset.path);if(row?.directory)return await browse({kind:'tree',directory:row.id,offset:0});return toast(tr('请从文件列表查看该文件'));}if(a==='tool-evidence'){const row=s.tools.find(r=>r.id===t.dataset.id);return modal(ui`<h2 id="dialog-title">${escape(row.name)} · 识别依据</h2><code>${escape(row.path)}</code><pre class="native-output">${escape(JSON.stringify(row.evidence,null,2))}</pre><div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}if(a==='directory')return await browse({...s.browser.scope,directory:t.dataset.id,kind:'tree',offset:0},true);if(a==='file-back')return await browse(s.history.pop());if(a==='files-page')return await browse({...s.browser.scope,offset:Number(t.dataset.offset)});if(a==='files-close'){s.browser=null;s.history=[];return render();}if(a==='inspect'){const r=await api('inspect',{id:t.dataset.id,scanId:scanId()});return modal(ui`<h2 id="dialog-title">内容片段</h2>${r.logMetadata?`<pre class="native-output">${escape(JSON.stringify(r.logMetadata,null,2))}</pre>`:''}${r.excerpt?`<pre class="native-output">${escape(r.excerpt)}</pre>`:`<p>${escape(tr(r.summary))}</p>`}<small>${r.bytesRead?bytes(r.bytesRead):tr('仅元数据')}${r.truncated?tr(' · 片段'):''}</small><div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}if(a==='preview-caches')return await preview(true);if(a==='preview')return await preview();if(a==='show-plan')return await showPlan();if(a==='plan-page')return await showPlan(Number(t.dataset.offset));if(a==='execute'){if(!s.all&&!s.picked.size)return toast(tr('请勾选预览内需要整理的文件'));if(s.plan.personal&&!document.querySelector('#native-personal-confirm')?.checked)return toast(tr('请先确认会话和记忆的影响'));const method=document.querySelector('#parity-method')?.value||'trash';if(method==='permanent'&&!document.querySelector('#parity-permanent-confirm')?.checked)return toast(tr('请明确确认永久删除'));const body={planId:s.plan.id,ids:[...s.picked],all:s.all,method,confirmation:method==='permanent'?'PERMANENT_REVIEWED_FILES':'TRASH_REVIEWED_FILES',personalConfirmation:s.plan.personal?'ACKNOWLEDGE_HISTORY_LOSS':undefined};t.disabled=true;close();return await start('execute',body);}if(a==='receipts')return await receipt();if(a==='receipt-page')return await receipt(s.receiptJob,Number(t.dataset.offset));if(a==='errors'||a==='associations')return await diagnostic(a);if(a==='diagnostic-page')return await diagnostic(t.dataset.type,Number(t.dataset.offset));if(a.startsWith('export-')){const result=await api('export',{kind:a.slice(7),format:s.exportFormat||'json',planId:s.plan?.id,scanId:scanId(),jobId:s.receiptJob});return toast(tr('已导出：')+result.path);}if(a==='summary')return await summary(t.dataset.id);if(a==='project-summary'){const root=await api('files',{project:t.dataset.id,kind:'tree',scanId:scanId()});return await summary(root.rootId);}if(a==='summary-confirm'){const p=s.pendingSummary;close();return await start('ai/summary',{previewId:p.id,revision:p.revision,confirmation:'SUMMARIZE_SELECTED_RESOURCE'});}if(a==='analyze'){const p=await api('ai/payload',{scanId:scanId()});s.pendingAnalysis=p;return modal(ui`<h2 id="dialog-title">审阅 AI 判读输入</h2><p>发送至 ${escape(p.destination)} · ${escape(p.model)}</p><span class="quiet-tag">文档读取已禁用</span><pre class="native-output">${escape(JSON.stringify(p.payload,null,2))}</pre><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('analyze-confirm',tr('发送元数据并判读'))}</div>`);}if(a==='analyze-confirm'){const p=s.pendingAnalysis;close();return await start('ai/analyze',{scanId:p.scanId,revision:p.revision,confirmation:'SEND_METADATA_FOR_ADVICE'});}if(a==='models')return await start('models');if(a==='model-review'){const m=s.boot.models.models.find(m=>m.id===t.dataset.id);s.model=m;return modal(ui`<h2 id="dialog-title">移除本地模型</h2><p>${escape(m.name)} · ${bytes(m.bytes)}</p><code>${escape(m.digest)}</code><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('model-delete',tr('确认通过 Ollama 移除'))}</div>`);}if(a==='model-delete'){close();return await start('models/delete',{id:s.model.id,confirmation:'DELETE_OLLAMA_MODEL'});}if(a==='mole')return await start('mole/preview',{command:t.dataset.command});}catch(error){toast(tr(error.message));if(dialog.open&&dialog.querySelector('[data-waiting]'))close();t.disabled=false;}});
refresh().catch(error=>{app.innerHTML=ui`<section class="panel"><h1>无法连接 Rust 服务</h1><p>${escape(error.message)}</p></section>`;});

function exportFormat(){return `<select data-export-format aria-label="${tr('导出格式')}"><option value="json">JSON</option><option value="csv" ${s.exportFormat==='csv'?'selected':''}>CSV</option></select>`;}
function cleanPage(){const p=s.moleLatest||s.boot.molePreview;return `<section class="panel"><div class="section-header"><h2>${tr('Mole 深度清理')}</h2><div class="parity-filters">${btn('mole',tr('生成清理预览'),{kind:'secondary',disabled:!!busy(),extra:'data-command="clean"'})}${btn('parity-mole-output',tr('查看原始输出'),{kind:'text'})}</div></div>${p?`<small>${time(p.createdAt)} · ${p.success?tr('预览完成'):tr('预览失败')}</small>`:''}<div class="parity-filters">${btn('parity-mole-plan',tr('按范围审阅清理'),{disabled:!!busy()||!p?.success||p.command!=='clean'||p.used})}${btn('parity-mole-whole',tr('整次 Mole 清理'),{kind:'secondary',disabled:!!busy()||!p?.success||p.command!=='clean'||p.used})}</div><details><summary>${tr('其他 Mole 命令预览')}</summary><div class="native-mole-actions">${['purge','installer','optimize'].map(c=>btn('mole',c+' --dry-run',{kind:'secondary',disabled:!!busy(),extra:`data-command="${c}"`})).join('')}</div></details></section><section class="panel"><div class="section-header"><h2>${tr('缓存与日志')}</h2>${btn('preview-caches',tr('生成逐文件预览'),{disabled:!!busy()||!scanId()||s.boot.stale})}</div>${btn('parity-candidates',tr('历史日志与下载的安装包'),{kind:'secondary',disabled:!scanId()||!!busy()})}${btn('parity-history',tr('整理历史'),{kind:'text'})}${s.plan?btn('show-plan',tr('查看预览'),{kind:'text'}):''}</section>`;}
function tools(){const h=s.harnesses?.rows||[],answers=s.harnessAnswers?.items||[];return `<section class="panel"><div class="section-header"><h2>${tr('候选工具')}${countTag(h.length)}</h2>${btn('parity-harness',tr('审阅结构并识别'),{kind:'secondary',disabled:!h.length||!!busy()||!s.boot.config.configured})}${s.harnessAnswers?.nextOffset!=null?btn('parity-harness-next',tr('识别下一批'),{kind:'secondary',disabled:!!busy()}):''}</div>${h.map(c=>{const cached=s.harnesses.knowledge?.find(k=>k.path===c.path&&k.fingerprint===c.fingerprint)?.analysis;const a=answers.find(a=>a.id===c.id)||cached;return `<article class="native-summary-row"><div><strong>${escape(c.name)}</strong><code class="native-path">${escape(pathLabel(c.path))}</code>${a?`<p>${escape(a.name||'')} · ${escape(a.kind)} · ${escape(a.confidence)}</p><small>${escape(a.reason)} · ${escape(a.uncertainty)}</small>`:`<small>${tr('身份待确认')}</small>`}</div></article>`;}).join('')}${(c=>meta([[tr('结构样本'),count(c.sampledFiles),c.sampledFiles||0],[tr('待补充样本'),count(c.deferred),c.deferred||0]]))(s.harnesses?.coverage||{})}</section>`+originalTools();}
function assistant(){const a=s.advice,filter=s.adviceFilter||'all';const rows=(a?.items||[]).filter(r=>filter==='all'||r.recommendation===filter);return `<section class="panel"><div class="section-header"><h2>${tr('AI 风险建议')}</h2><span class="quiet-tag">${tr('文档读取已禁用')}</span></div><div class="parity-filters"><select id="parity-advice-source"><option value="tools">${tr('AI 工具专项占用')}</option><option value="plan" ${s.adviceSource==='plan'?'selected':''}>${tr('当前逐文件清理清单')}</option><option value="mole-plan" ${s.adviceSource==='mole-plan'?'selected':''}>${tr('Mole 可视化清理清单')}</option></select>${btn('parity-advice',tr('审阅元数据并判读'),{disabled:!!busy()||!s.boot.config.configured||(!scanId()&&!s.molePlan)})}${btn('config',tr('模型连接'),{kind:'secondary'})}</div>${a?`<p>${escape(a.summary)}</p><div class="parity-filters"><select id="parity-advice-filter"><option value="all">${tr('全部建议')}</option>${['keep','review','consider'].map(k=>`<option value="${k}" ${filter===k?'selected':''}>${({keep:tr('保留'),review:tr('需要审阅'),consider:tr('可考虑')})[k]}</option>`).join('')}</select>${exportFormat()}${btn('parity-advice-export',tr('导出全部建议'),{kind:'text'})}${a.nextOffset!=null?btn('parity-advice-next',tr('判读下一批'),{kind:'secondary',disabled:!!busy()}):''}</div>${rows.map(r=>`<article class="parity-advice-row"><span class="quiet-tag">${({keep:tr('保留'),review:tr('需要审阅'),consider:tr('可考虑')})[r.recommendation]} · ${escape(r.risk)}</span><div><strong>${escape(r.name)}</strong><code class="native-path">${escape(pathLabel(r.path))}</code><p>${escape(r.reason)}</p><small>${escape(r.uncertainty)}</small></div><b>${bytes(r.bytes)}</b></article>`).join('')}`:''}</section>`;}
async function showMolePlan(){const p=s.molePlan;if(!p)return;s.molePicked??=new Set();modal(`<h2 id="dialog-title">${tr('Mole 可视化清理清单')}</h2><div class="native-plan-list">${p.groups.map(g=>`<article class="native-plan-row"><label><input type="checkbox" data-mole-group="${g.id}" ${s.molePicked.has(g.id)?'checked':''} ${g.selectable?'':'disabled'}/><strong>${escape(g.name)}</strong><b>${g.bytes!=null?bytes(g.bytes):escape(g.estimate||'')}</b></label><code>${escape(g.path)}</code><small>${escape(g.category)}${g.blocked?' · '+escape(g.blocked):''}</small>${g.selectable?btn('parity-mole-files',tr('展开文件'),{kind:'text',extra:`data-id="${g.id}"` }):''}</article>`).join('')}</div><div class="parity-filters"><label>${tr('处理方式')}<select id="parity-mole-method"><option value="trash">${tr('移到废纸篓')}</option><option value="permanent">${tr('永久删除')}</option></select></label><label data-permanent-ack hidden><input type="checkbox" id="parity-mole-permanent"/>${tr('若选择永久删除，我确认所勾选文件无法从废纸篓恢复')}</label></div><div class="dialog-actions native-plan-actions">${exportFormat()}${btn('parity-mole-export',tr('导出清单'),{kind:'secondary'})}${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-mole-selected',tr('确认处理勾选范围'))}</div>`);}
async function showMoleFiles(group,offset=0){const r=await api('mole/plan/files',{planId:s.molePlan.id,groupId:group,offset});modal(`<h2 id="dialog-title">${tr('清单内文件')}</h2><div class="native-plan-list">${r.rows.map(row=>`<article class="native-plan-row"><code>${escape(row.path)}</code><span>${row.directory?tr('文件夹'):tr('文件')} · ${bytes(row.bytes)}</span></article>`).join('')}</div>${pagination(offset,100,r.total,'parity-mole-files-page')}<div class="dialog-actions">${btn('parity-mole-plan-back',tr('返回清单'),{kind:'secondary'})}${btn('close',tr('关闭'))}</div>`);s.moleFileGroup=group;}
async function advicePreview(offset=0){s.adviceSource=document.querySelector('#parity-advice-source')?.value||s.adviceSource||'tools';let source=s.adviceSource;if(source==='plan'&&!s.plan||source==='mole-plan'&&!s.molePlan){toast(tr('请先生成逐文件预览'));return;}const p=await api('ai/review-payload',{scanId:scanId(),source,planId:source==='mole-plan'?s.molePlan?.id:s.plan?.id,offset});s.adviceInput=p;modal(`<h2 id="dialog-title">${tr('审阅 AI 判读输入')}</h2><p>${escape(p.destination)} · ${escape(p.model)} · ${count(p.offset+1)}–${count(Math.min(p.offset+20,p.total))} / ${count(p.total)}</p><span class="quiet-tag">${tr('文档读取已禁用')}</span><pre class="native-output">${escape(JSON.stringify(p.payload,null,2))}</pre><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-advice-confirm',tr('发送元数据并判读'))}</div>`);}
async function candidateList(offset=0){const r=await api('candidates',{scanId:scanId(),offset});s.candidateRows=r.rows;s.candidatePicked??=new Set();modal(`<h2 id="dialog-title">${tr('历史日志与下载的安装包')}</h2><div class="native-plan-list">${r.rows.map(row=>`<article class="native-plan-row"><label><input type="checkbox" data-candidate-file="${row.id}" ${s.candidatePicked.has(row.id)?'checked':''} ${row.selectable?'':'disabled'}/><strong>${escape(row.name)}</strong><b>${bytes(row.bytes)}</b></label><code>${escape(row.path)}</code><small>${escape(row.reason||kinds[row.kind])}</small></article>`).join('')||`<p>${tr('没有匹配的文件')}</p>`}</div>${pagination(offset,100,r.total,'parity-candidates-page')}<div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-candidates-preview',tr('预览勾选文件'))}</div>`);}
async function history(offset=0){const r=await api('history',{offset});modal(`<h2 id="dialog-title">${tr('整理历史')}</h2><div class="native-plan-list">${r.rows.map(j=>`<article class="native-summary-row"><span>${time(j.createdAt)}</span><b>${bytes(j.bytes)}</b><span>${count(j.records)} ${tr('条记录')}</span>${btn('parity-history-receipt',tr('查看逐文件去向'),{kind:'text',extra:`data-id="${j.jobId}"`})}</article>`).join('')||`<p>${tr('暂无记录')}</p>`}</div>${pagination(offset,100,r.total,'parity-history-page')}<div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}
document.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-export-format]'))s.exportFormat=t.value;if(['parity-method','parity-mole-method'].includes(t.id)){const ack=dialog.querySelector('[data-permanent-ack]');if(ack){ack.hidden=t.value!=='permanent';ack.querySelector('input').checked=false;}}if(t.dataset.moleGroup){s.molePicked??=new Set();t.checked?s.molePicked.add(t.dataset.moleGroup):s.molePicked.delete(t.dataset.moleGroup);}if(t.dataset.candidateFile){s.candidatePicked??=new Set();t.checked?s.candidatePicked.add(t.dataset.candidateFile):s.candidatePicked.delete(t.dataset.candidateFile);}if(t.id==='parity-advice-source')s.adviceSource=t.value;if(t.id==='parity-legacy-section'){legacy(t.value).catch(e=>toast(e.message));}if(t.id==='parity-advice-filter'){s.adviceFilter=t.value;render();}});
document.addEventListener('click',async event=>{const t=event.target.closest('[data-action^="parity-"]');if(!t||t.disabled)return;const a=t.dataset.action;try{
 if(a==='parity-mole-output'){const running=busy();const p=running?.stats?.output?{output:running.stats.output}:await api('mole/output');return modal(`<h2 id="dialog-title">Mole · ${tr('原始输出')}</h2><pre class="native-output">${escape(p?.output||tr('尚无输出'))}</pre><div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}
 if(a==='parity-mole-plan'){if(s.molePlan?.previewId===(s.moleLatest||s.boot.molePreview)?.id)return showMolePlan();s.molePicked=new Set();close();return await start('mole/plan',{previewId:(s.moleLatest||s.boot.molePreview).id});}
 if(a==='parity-mole-files')return await showMoleFiles(t.dataset.id);
 if(a==='parity-mole-files-page')return await showMoleFiles(s.moleFileGroup,Number(t.dataset.offset));
 if(a==='parity-mole-plan-back')return showMolePlan();
 if(a==='parity-mole-selected'){if(!s.molePicked?.size)return toast(tr('请选择清理范围'));const method=document.querySelector('#parity-mole-method').value;if(method==='permanent'&&!document.querySelector('#parity-mole-permanent').checked)return toast(tr('请明确确认永久删除'));close();return await start('mole/plan/execute',{planId:s.molePlan.id,ids:[...s.molePicked],method,confirmation:method==='permanent'?'PERMANENT_REVIEWED_FILES':'TRASH_REVIEWED_FILES'});}
 if(a==='parity-mole-whole')return modal(`<h2 id="dialog-title">${tr('确认整次 Mole 永久清理')}</h2><p>${tr('执行 Mole clean 的完整规则范围，不限于页面上的勾选。文件将永久删除，停止不会恢复已经处理的文件。')}</p><pre class="native-output">${escape((s.moleLatest||s.boot.molePreview)?.output||'')}</pre><label><input type="checkbox" id="parity-whole-ack"/>${tr('我已审阅预览，确认执行整次永久清理')}</label><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-mole-whole-confirm',tr('确认永久清理'))}</div>`);
 if(a==='parity-mole-whole-confirm'){if(!document.querySelector('#parity-whole-ack').checked)return toast(tr('请先确认完整范围'));close();return await start('mole/execute',{previewId:(s.moleLatest||s.boot.molePreview).id,confirmation:'PERMANENT_MOLE_CLEAN'});}
 if(a==='parity-advice')return await advicePreview(0);
 if(a==='parity-advice-next')return await advicePreview(s.advice.nextOffset);
 if(a==='parity-advice-confirm'){close();return await start('ai/review',{inputId:s.adviceInput.id,confirmation:'SEND_METADATA_FOR_ADVICE'});}
 if(a==='parity-advice-export'){const r=await api('export',{kind:'advice',format:s.exportFormat||'json',scanId:scanId()});return toast(tr('已导出：')+r.path);}
 if(a==='parity-harness'){const rows=s.harnesses.rows.slice(0,12);s.harnessOffset=0;return modal(`<h2 id="dialog-title">${tr('审阅候选结构')}</h2><p>${escape(s.boot.config.baseUrl)} · ${escape(s.boot.config.model)}</p><pre class="native-output">${escape(JSON.stringify(rows.map(r=>r.metadata),null,2))}</pre><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-harness-confirm',tr('发送元数据并识别'))}</div>`);}
 if(a==='parity-harness-next'){s.harnessOffset=s.harnessAnswers.nextOffset;const rows=s.harnesses.rows.slice(s.harnessOffset,s.harnessOffset+12);return modal(`<h2 id="dialog-title">${tr('审阅候选结构')}</h2><p>${escape(s.boot.config.baseUrl)} · ${escape(s.boot.config.model)}</p><pre class="native-output">${escape(JSON.stringify(rows.map(r=>r.metadata),null,2))}</pre><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-harness-confirm',tr('发送元数据并识别'))}</div>`);}if(a==='parity-harness-confirm'){close();return await start('harnesses/analyze',{scanId:scanId(),offset:s.harnessOffset||0,confirmation:'SEND_METADATA_FOR_ADVICE'});}
 if(a==='parity-candidates')return await candidateList();if(a==='parity-candidates-page')return await candidateList(Number(t.dataset.offset));
 if(a==='parity-candidates-preview'){s.plan=await api('preview',{scanId:scanId(),fileIds:[...(s.candidatePicked||[])],categories:['log','installer']});s.picked.clear();s.all=false;return await showPlan();}
 if(a==='parity-tool-category')return await browse({tool:t.dataset.id,kind:t.dataset.kind,offset:0});if(a==='errors-retry'){close();return await start('errors/retry',{scanId:scanId()});}if(a==='parity-measure')return await start('files/measure',{scanId:scanId(),id:t.dataset.id});if(a==='parity-project-details')return await projectDetails(t.dataset.id);if(a==='parity-project-details-page')return await projectDetails(s.detailProject,Number(t.dataset.offset));if(a==='parity-use-model'){const model=s.boot.models.models.find(m=>m.id===t.dataset.id);await api('ai/config',{provider:'ollama',baseUrl:s.boot.models.endpoint||'http://127.0.0.1:11434',model:model.name,clearKey:true});await refresh();return toast(tr('模型连接已保存'));}if(a==='parity-file-filter')return await browse({...s.browser.scope,query:document.querySelector('#parity-file-query').value,sort:document.querySelector('#parity-file-sort').value,offset:0});
 if(a==='parity-diagnostic-filter')return await diagnostic(s.diagnosticType,0,{query:document.querySelector('#parity-diagnostic-query').value,status:document.querySelector('#parity-diagnostic-status').value});if(a==='parity-diagnostic-export'){const r=await api('export',{kind:s.diagnosticType,format:s.exportFormat||'json',scanId:scanId()});return toast(tr('已导出：')+r.path);}if(a==='parity-history')return await history();if(a==='parity-history-page')return await history(Number(t.dataset.offset));if(a==='parity-history-receipt')return await receipt(t.dataset.id);
 if(a==='parity-legacy')return await legacy();if(a==='parity-legacy-page')return await legacy(s.legacySection,Number(t.dataset.offset));if(a==='parity-legacy-export'){const r=await api('export',{kind:'legacy'});return toast(tr('已导出：')+r.path);}if(a==='parity-import')return modal(`<h2 id="dialog-title">${tr('导入 Web 历史')}</h2><label>${tr('Web JSON 导出或 latest-state.json 路径')}<input id="parity-import-path" type="text"/></label><div class="dialog-actions">${btn('close',tr('取消'),{kind:'secondary'})}${btn('parity-import-confirm',tr('确认导入历史'))}</div>`);
 if(a==='parity-import-confirm'){const r=await api('import/legacy',{path:document.querySelector('#parity-import-path').value,confirmation:'IMPORT_WEB_HISTORY'});close();toast(tr('已导入历史；清理前需重新扫描'));return await refresh();}
 if(a==='parity-mole-export'){const r=await api('export',{kind:'mole-plan',planId:s.molePlan.id,format:s.exportFormat||'json'});return toast(tr('已导出：')+r.path);}
 }catch(error){toast(tr(error.message));}});

async function projectDetails(id,offset=0){const p=await api('projects/details',{scanId:scanId(),projectId:id,offset});s.detailProject=id;modal(`<h2 id="dialog-title">${escape(p.name)} · ${tr('关联与用途')}</h2><code>${escape(p.path)}</code><p>${escape(p.description?.description||'')}</p><div class="native-plan-list">${p.rows.map(r=>`<article class="native-plan-row"><strong>${escape(r.title||kinds[r.kind]||r.kind)}</strong><code>${escape(r.path)}</code><small>${escape(r.tool||'')} · ${escape(r.status)} · ${r.managed?tr('共享数据库，空间不按记录分摊'):bytes(r.bytes)}</small><p>${escape(r.details?.description||r.reason)}</p></article>`).join('')||`<p>${tr('没有关联记录')}</p>`}</div>${pagination(offset,100,p.total,'parity-project-details-page')}<div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}

async function legacy(section,offset=0){const r=await api('legacy',{section,offset});s.legacySection=r.section;modal(`<h2 id="dialog-title">${tr('Web 历史记录')}</h2><div class="parity-filters"><select id="parity-legacy-section">${r.sections.map(k=>`<option value="${escape(k)}" ${k===r.section?'selected':''}>${escape(k)}</option>`).join('')}</select>${btn('parity-legacy-export',tr('导出历史'),{kind:'secondary'})}</div><pre class="native-output">${escape(JSON.stringify(r.rows,null,2))}</pre>${pagination(offset,100,r.total,'parity-legacy-page')}<div class="dialog-actions">${btn('close',tr('关闭'))}</div>`);}
